import{_ as a,o as n,c as e,a5 as i}from"./chunks/framework.DJo0M80U.js";const h=JSON.parse('{"title":"34. Bitfields and Memory Packing","description":"The Little Book of C — 34. Bitfields and Memory Packing","frontmatter":{"title":"34. Bitfields and Memory Packing","date":"2026-07-04","categories":["C 教程"],"tags":["C","Little Book of C","Structuring Data"],"description":"The Little Book of C — 34. Bitfields and Memory Packing","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","section":34,"sidebarWeight":34,"lang":"en-US","alternateEn":"/posts/c教程/en-US/04-Structuring Data/034-Bitfields and Memory Packing","alternateZh":"/posts/c教程/zh-CN/04-数据结构/034-Bitfields and Memory Packing"},"headers":[],"relativePath":"posts/c教程/en-US/04-Structuring Data/034-Bitfields and Memory Packing.md","filePath":"posts/c教程/en-US/04-Structuring Data/034-Bitfields and Memory Packing.md","lastUpdated":1790163617000}'),t={name:"posts/c教程/en-US/04-Structuring Data/034-Bitfields and Memory Packing.md"};function p(l,s,o,r,c,d){return n(),e("div",null,[...s[0]||(s[0]=[i(`<p>[中文版本](/posts/c教程/zh-CN/04-数据结构/034-Bitfields and Memory Packing)</p><p>C lets you control data layout down to the bit level using bitfields. They allow you to store small values compactly inside a struct, perfect for flags, configuration registers, or communication protocols. Combined with packing, you can squeeze data into minimal space while still keeping it easy to manipulate symbolically.</p><h4 id="what-is-a-bitfield" tabindex="-1">What Is a Bitfield? <a class="header-anchor" href="#what-is-a-bitfield" aria-label="Permalink to &quot;What Is a Bitfield?&quot;">​</a></h4><p>A bitfield lets you define the exact number of bits to allocate for a field inside a<code>struct</code>.</p><p>Example:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>struct Flags {</span></span>
<span class="line"><span>    unsigned int is_visible : 1;</span></span>
<span class="line"><span>    unsigned int is_enabled : 1;</span></span>
<span class="line"><span>    unsigned int has_error  : 1;</span></span>
<span class="line"><span>};</span></span></code></pre></div><p>Here, each field uses just 1 bit instead of a full 4-byte<code>int</code>. That means 8 such flags fit comfortably in one byte.</p><h4 id="declaring-and-using-bitfields" tabindex="-1">Declaring and Using Bitfields <a class="header-anchor" href="#declaring-and-using-bitfields" aria-label="Permalink to &quot;Declaring and Using Bitfields&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>struct Status {</span></span>
<span class="line"><span>    unsigned int connected : 1;</span></span>
<span class="line"><span>    unsigned int error     : 1;</span></span>
<span class="line"><span>    unsigned int active    : 1;</span></span>
<span class="line"><span>    unsigned int reserved  : 5; // padding bits</span></span>
<span class="line"><span>};</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    struct Status s = {1, 0, 1, 0};</span></span>
<span class="line"><span>    printf(&quot;Connected: %u, Active: %u\\n&quot;, s.connected, s.active);</span></span>
<span class="line"><span>    s.error = 1;</span></span>
<span class="line"><span>    printf(&quot;Error now: %u\\n&quot;, s.error);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Connected: 1, Active: 1</span></span>
<span class="line"><span>Error now: 1</span></span></code></pre></div><p>Even though there are 4 fields, the entire struct typically occupies only 1 byte.</p><h4 id="tiny-code" tabindex="-1">Tiny Code <a class="header-anchor" href="#tiny-code" aria-label="Permalink to &quot;Tiny Code&quot;">​</a></h4><p>Here’s a complete example demonstrating packed flags and printing bit values:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>struct DeviceStatus {</span></span>
<span class="line"><span>    unsigned int powered_on : 1;</span></span>
<span class="line"><span>    unsigned int connected  : 1;</span></span>
<span class="line"><span>    unsigned int has_error  : 1;</span></span>
<span class="line"><span>    unsigned int battery_low: 1;</span></span>
<span class="line"><span>    unsigned int reserved   : 4;</span></span>
<span class="line"><span>};</span></span>
<span class="line"><span>void print_bits(unsigned char byte) {</span></span>
<span class="line"><span>    for (int i = 7; i &gt;= 0; i--)</span></span>
<span class="line"><span>        printf(&quot;%d&quot;, (byte &gt;&gt; i) &amp; 1);</span></span>
<span class="line"><span>    printf(&quot;\\n&quot;);</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    struct DeviceStatus d = {1, 1, 0, 0, 0};</span></span>
<span class="line"><span>    printf(&quot;Size of DeviceStatus: %zu bytes\\n&quot;, sizeof(d));</span></span>
<span class="line"><span>    unsigned char *raw = (unsigned char*)&amp;d;</span></span>
<span class="line"><span>    printf(&quot;Binary layout: &quot;);</span></span>
<span class="line"><span>    print_bits(*raw);</span></span>
<span class="line"><span>    d.has_error = 1;</span></span>
<span class="line"><span>    printf(&quot;Updated binary: &quot;);</span></span>
<span class="line"><span>    print_bits(*raw);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Output (may vary by platform):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Size of DeviceStatus: 1 bytes</span></span>
<span class="line"><span>Binary layout: 00000011</span></span>
<span class="line"><span>Updated binary: 00000111</span></span></code></pre></div><h4 id="nested-bitfields-example" tabindex="-1">Nested Bitfields Example <a class="header-anchor" href="#nested-bitfields-example" aria-label="Permalink to &quot;Nested Bitfields Example&quot;">​</a></h4><p>You can even use bitfields inside nested structs to create compact yet expressive data models:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>struct Sensor {</span></span>
<span class="line"><span>    unsigned id       : 4;  // 0–15</span></span>
<span class="line"><span>    unsigned type     : 3;  // 0–7</span></span>
<span class="line"><span>    unsigned active   : 1;  // boolean</span></span>
<span class="line"><span>};</span></span>
<span class="line"><span>struct Device {</span></span>
<span class="line"><span>    struct Sensor sensors[2];</span></span>
<span class="line"><span>};</span></span></code></pre></div><p>Each sensor entry now fits neatly into a single byte.</p><h4 id="memory-packing" tabindex="-1">Memory Packing <a class="header-anchor" href="#memory-packing" aria-label="Permalink to &quot;Memory Packing&quot;">​</a></h4><p>By default, compilers may insert padding bytes to align fields for faster access. If you want tighter packing, for example, when saving binary data to a file or sending over a network, you can request packed structs.</p><p>Compiler directives differ by system:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#pragma pack(push, 1)</span></span>
<span class="line"><span>struct Packet {</span></span>
<span class="line"><span>    char type;</span></span>
<span class="line"><span>    unsigned int length;</span></span>
<span class="line"><span>    short checksum;</span></span>
<span class="line"><span>};</span></span>
<span class="line"><span>#pragma pack(pop)</span></span></code></pre></div><p>Now the struct is tightly packed without alignment padding between fields.</p><h4 id="bitfields-in-real-systems" tabindex="-1">Bitfields in Real Systems <a class="header-anchor" href="#bitfields-in-real-systems" aria-label="Permalink to &quot;Bitfields in Real Systems&quot;">​</a></h4><p>Bitfields are used everywhere in systems programming:</p><ul><li>Hardware control registers: Represent on/off bits for devices.</li><li>Network protocols: Flags in TCP, UDP, or IP headers.</li><li>Compression and serialization: Compact representation of status or metadata.</li><li>Embedded systems: Save every byte of RAM in microcontrollers.</li></ul><h4 id="limitations" tabindex="-1">Limitations <a class="header-anchor" href="#limitations" aria-label="Permalink to &quot;Limitations&quot;">​</a></h4><ul><li>Bitfield ordering (which bit is “first”) is implementation-dependent, varies by compiler and platform.</li><li>They cannot cross word boundaries reliably across architectures.</li><li>Bitfields cannot be directly addressed by pointers (<code>&amp;field</code> not allowed).</li><li>Endianness matters if transmitting across different systems.</li></ul><p>For portable bit-level control (especially in networking), many engineers use explicit bitwise operators instead.</p><h4 id="manual-bitwise-control" tabindex="-1">Manual Bitwise Control <a class="header-anchor" href="#manual-bitwise-control" aria-label="Permalink to &quot;Manual Bitwise Control&quot;">​</a></h4><p>Sometimes you’ll prefer manual masks and shifts:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>unsigned char flags = 0;</span></span>
<span class="line"><span>flags |= (1 &lt;&lt; 0); // set bit 0</span></span>
<span class="line"><span>flags |= (1 &lt;&lt; 2); // set bit 2</span></span>
<span class="line"><span>flags &amp;= ~(1 &lt;&lt; 0); // clear bit 0</span></span></code></pre></div><p>This approach is more portable and explicit, but less readable for large sets of flags.</p><h4 id="why-it-matters" tabindex="-1">Why It Matters <a class="header-anchor" href="#why-it-matters" aria-label="Permalink to &quot;Why It Matters&quot;">​</a></h4><p>Bitfields give you compact control over memory layout and binary representation. They’re critical in:</p><ul><li>Embedded firmware</li><li>Network stacks</li><li>Kernel drivers</li><li>Compression libraries</li></ul><p>They make your code expressive and efficient, as long as you understand alignment and portability issues.</p><h4 id="try-it-yourself" tabindex="-1">Try It Yourself <a class="header-anchor" href="#try-it-yourself" aria-label="Permalink to &quot;Try It Yourself&quot;">​</a></h4><ol><li>Define a struct<code>Permissions</code> with 1-bit fields for<code>read</code>,<code>write</code>, and<code>execute</code>.</li><li>Print its size and check how compact it is.</li><li>Use a bitfield struct to represent a simplified TCP header (flags like SYN, ACK, FIN).</li><li>Use<code>#pragma pack(1)</code> and observe the size difference.</li><li>Write functions to set, clear, and toggle bits using bitwise operators.</li></ol><p>Bitfields are where C meets the hardware. They let you talk to the machine not just in bytes, but in bits, the true language of computers. Next, you’ll revisit enumerations and see how they complement these compact structures by giving symbolic meaning to values.</p>`,43)])])}const g=a(t,[["render",p]]);export{h as __pageData,g as default};
